def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0]
    stack = [0]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)
                stack.append(v)

    sub = [0] * n
    for u in reversed(order):
        s = w[u]
        for v in adj[u]:
            if parent[v] == u:
                s += sub[v]
        sub[u] = s

    total = sub[0]
    ans = [0] * n
    depth = [0] * n
    acc = 0
    for u in order:
        if u:
            depth[u] = depth[parent[u]] + 1
        acc += w[u] * depth[u]
    ans[0] = acc

    for u in order:
        if u == 0:
            continue
        p = parent[u]
        ans[u] = ans[p] - sub[u] + (total - sub[u])
    return ans
